import{_ as a,o as i,c as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"DateinameFuerDVAuswaehlen","description":"","frontmatter":{"title":"DateinameFuerDVAuswaehlen","source_pageid":25,"source_revision":316},"headers":[],"relativePath":"reporting/rap/dateinamefuerdvauswaehlen.md","filePath":"reporting/rap/dateinamefuerdvauswaehlen.md"}'),r={name:"reporting/rap/dateinamefuerdvauswaehlen.md"};function t(l,e,d,h,p,o){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="dateinamefuerdvauswaehlen" tabindex="-1">DateinameFuerDVAuswaehlen <a class="header-anchor" href="#dateinamefuerdvauswaehlen" aria-label="Permalink to &quot;DateinameFuerDVAuswaehlen&quot;">​</a></h1><h2 id="beschreibung" tabindex="-1">Beschreibung <a class="header-anchor" href="#beschreibung" aria-label="Permalink to &quot;Beschreibung&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">procedure</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DateinameFuerDVAuswaehlen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Vor dem Speichern einer PDF-Ausgabe in der Dokumentenverwaltung können Sie mit dieser Prozedur einen eigenen Dateinamen abfragen. Der eingegebene Name ersetzt den Namen der Reportvorlage im schülerspezifischen Dateinamen. Der Aufruf erfolgt typischerweise im Ereignis <code>ReportBeforePrint</code>. Das ist zum Beispiel für Serienbriefe hilfreich, deren Text erst beim Start aus einer RTF-Datei geladen wird.</p><h2 id="ruckgabewert" tabindex="-1">Rückgabewert <a class="header-anchor" href="#ruckgabewert" aria-label="Permalink to &quot;Rückgabewert&quot;">​</a></h2><p>Beispiel: Zur Vorlage <code>RTFBrief.rtm</code> würde normalerweise eine Datei wie <code>RTFBrief_2013_05_24.pdf</code> abgelegt. Der Zweck des Briefes ist daraus nicht erkennbar. Mit <code>DateinameFuerDVAuswaehlen</code> kann stattdessen <strong>Hausaufgabenmahnbrief</strong> eingegeben werden. Die abgelegte Datei heißt dann <code>Hausaufgabenmahnbrief_2013_05_24.pdf</code>. Das Datum dient hier nur als Beispiel.</p><h2 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">procedure</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ReportBeforePrint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> begin</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  DateinameFuerDVAuswaehlen;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Hinweis: Wenn der RTF-Text aus einer externen Datei geladen wird, so wird deren Dateiname verwendet, eine manuelle Eingabe erfolgt dann nicht.</p><p><strong>Zurück zu <a href="/reporting/rap.html">RAP-Funktionen</a></strong></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=DateinameFuerDVAuswaehlen" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 316.</p>`,12)])])}const g=a(r,[["render",t]]);export{c as __pageData,g as default};
